window.futvizVista("equipo-completo","<div class=\"rx-mount\" data-rx=\"venn\" data-rx-id=\"equipo-completo\" style=\"min-height:900px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"equipo-completo\"]={\"id\":\"equipo-completo\",\"titulo\":\"Equipo completo\",\"bajada\":\"Los equipos que est\u00e1n en el top de las cinco ligas en ataque, defensa y posesi\u00f3n a la vez, y cu\u00e1ntos hay.\",\"pregunta\":\"\u00bfQu\u00e9 equipos destacan a la vez en ataque, defensa y control?\",\"tabla\":\"equipo-completo\",\"queMirar\":\"Muestra qu\u00e9 equipos est\u00e1n entre los mejores de las cinco ligas en tres cosas a la vez: el xG que crean, el xG que conceden y el tiempo que tienen el bal\u00f3n. Cada c\u00edrculo agrupa a los que destacan en una de ellas, y el centro re\u00fane a los que destacan en las tres.\\nEl deslizador define qu\u00e9 tan exigente es \u00abentre los mejores\u00bb: es el porcentaje de arriba de las cinco ligas en esa temporada, de 5% a 30%. Las regiones de dos c\u00edrculos distinguen estilos, porque crear y conceder poco sin tener el bal\u00f3n no es lo mismo que tenerlo y no crear.\",\"fuente\":\"Understat y FBref\",\"venns\":[{\"id\":\"equipo\",\"tab\":\"Equipo completo\",\"pos\":\"Equipo\",\"plural\":\"equipos\",\"titulo\":\"El equipo completo\",\"sets\":[{\"nombre\":\"Ataca\",\"col\":\"ataca\",\"dec\":2,\"def\":\"xG a favor por partido, sin penales\"},{\"nombre\":\"Defiende\",\"col\":\"defiende\",\"dec\":2,\"inv\":true,\"def\":\"xG en contra por partido, sin penales: cuenta el que concede menos\"},{\"nombre\":\"Controla\",\"col\":\"controla\",\"dec\":1,\"def\":\"Posesi\u00f3n del bal\u00f3n, en %\"}]}],\"equipo\":true,\"ambito\":\"de los equipos de las cinco ligas\"};</script>");